        class _RNGShim:
    def __init__(self, seed: int):
        import random as _random
        self._seed = int(seed)
        self._r = _random.Random(self._seed)

    def random(self): return self._r.random()
    def uniform(self, a, b): return self._r.uniform(a, b)
    def randint(self, a, b): return self._r.randint(a, b)
    def randrange(self, *args): return self._r.randrange(*args)
    def choice(self, seq): return self._r.choice(seq)
    def choices(self, population, weights=None, cum_weights=None, k: int = 1):
        return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
    def sample(self, population, k: int): return self._r.sample(population, k)
    def shuffle(self, x):
        self._r.shuffle(x)
        return x
    def getrandbits(self, k: int): return self._r.getrandbits(k)

        from math import gcd

def generator(rng):
    # We generate integer major/minor radii R>r>=2 and sphere radius S>r.
    # We do not reveal R and r directly; instead we provide
    # area_core = a = R*r and volume_core = b = R*r^2, and sphere_area_core = S^2.
    # The target expression is r_i - r_o = 2 R S r / (S^2 - r^2).
    # We will compute the final reduced fraction to ensure it's nontrivial and reasonable in size.
    tries = 0
    while True:
        tries += 1
        if tries > 1000:
            # Fallback deterministic values matching constraints
            R, r, S = 8, 3, 13
        else:
            r = rng.randint(2, 12)
            R = rng.randint(r + 1, r + 12)
            # Ensure S > r and not too huge
            S = rng.randint(r + 1, R + r + 18)
        # Compute cores
        a = R * r
        b = R * r * r
        sa = S * S
        # Compute the reduced fraction for delta using integer-only arithmetic:
        # delta = 2 * a^3 * S / (S^2 * a^2 - b^2)
        num = 2 * (a ** 3) * S
        den = sa * (a ** 2) - (b ** 2)
        # Validity checks
        if den <= 0:
            continue
        g = gcd(num, den)
        m = num // g
        n = den // g
        # Nontriviality and size constraints
        if n == 1:
            continue  # avoid integer answers
        if m <= 0 or n <= 0:
            continue
        if m > 20000 or n > 20000:
            continue
        # Extra guard: avoid overly tiny or too simple fractions
        # Ensure some cancellation occurred (for variety) and value not too small
        # but don't force cancellation every time.
        if (num % den == 0):
            continue
        # Also ensure the torus parameters are not trivial
        if a <= 10 or b <= 20:
            continue
        return {
            'area_core': a,
            'volume_core': b,
            'sphere_area_core': sa
        }

